<script setup lang="ts">
const api=window.teachshelf;
import {onMounted,reactive,ref} from 'vue';
import {Archive,Check,Copy,Database,Download,FolderOpen,Globe,KeyRound,Monitor,Save,Server,Sparkles} from 'lucide-vue-next';
import {useLibrary} from '../stores/library';
const emit=defineEmits<{website:[]}>(),store=useLibrary();
const form=reactive({baseURL:'',model:'',apiKey:'',mcpEnabled:false,mcpPort:53142,theme:'system'}),showToken=ref(false),loaded=ref(false);
function fill(){const s=store.settings;if(s)Object.assign(form,{baseURL:s.ai.baseURL,model:s.ai.model,mcpEnabled:s.mcp.enabled,mcpPort:s.mcp.port,theme:s.theme});loaded.value=true;}
onMounted(async()=>{const result=await store.run(()=>api.settings(),'设置已加载');if(result){store.settings=result;fill();}});
async function saveAI(){const result=await store.run(()=>api.saveSettings({baseURL:form.baseURL,model:form.model,...(form.apiKey?{apiKey:form.apiKey}:{})}),'模型设置已保存');if(result){store.settings=result;form.apiKey='';}}
async function clearKey(){if(!await store.confirm('移除已保存的 API 密钥？','模型连接信息会保留，密钥将从本机安全存储中移除。','移除密钥'))return;const result=await store.run(()=>api.saveSettings({apiKey:''}),'密钥已移除');if(result)store.settings=result;}
async function saveMCP(){const result=await store.run(()=>api.saveSettings({mcpEnabled:form.mcpEnabled,mcpPort:Number(form.mcpPort)}),'MCP 设置已保存');if(result)store.settings=result;}
async function saveTheme(){const result=await store.run(()=>api.saveSettings({theme:form.theme}),'外观已更新');if(result)store.settings=result;}
async function backup(){const result=await store.run(()=>api.backupLibrary(),'资料库备份完成');if(result)store.status='备份已保存到 '+result;}
async function copyMCP(){await store.run(()=>api.copyMCPConfiguration(),'MCP 配置已复制');}
</script>
<template><section class="workspace settings-workspace"><header class="workspace-header"><div class="heading-block"><h1>设置</h1><p>资料库、模型连接与本机服务。</p></div></header><div class="settings-scroll"><div class="settings-content"><section class="settings-section"><h2><Database :size="19"/>本地资料库</h2><div class="settings-card"><div class="setting-row"><div><strong>当前资料库</strong><p class="path-text">{{store.snapshot?.root}}</p><p>JSON 索引与真实文件目录，可离线管理。</p></div><span class="tag">schema {{store.state.schemaVersion}}</span></div><div v-if="store.snapshot?.warnings.length" class="warning-banner"><p v-for="warning in store.snapshot.warnings" :key="warning">{{warning}}</p></div><div class="setting-actions"><button @click="store.chooseLibrary(true)" :disabled="!!store.busy"><Download :size="16"/>复制导入旧资料库…</button><button @click="store.chooseLibrary(false)" :disabled="!!store.busy"><FolderOpen :size="16"/>打开 Desktop 资料库…</button><button @click="backup" :disabled="!!store.busy"><Archive :size="16"/>备份完整资料库…</button></div><p class="field-note">导入会创建独立副本，原 Swift 资料库和课件保持不变。外部引用文件不会随资料库自动复制。</p></div></section><section class="settings-section"><h2><Sparkles :size="19"/>AI 助手</h2><form class="settings-card form-stack" @submit.prevent="saveAI"><label>API 基础地址<input type="url" v-model="form.baseURL" placeholder="https://api.example.com/v1" autocomplete="off" required/></label><label>模型名称<input v-model="form.model" placeholder="输入服务提供的模型 ID" autocomplete="off" required/></label><label>API 密钥<input type="password" v-model="form.apiKey" :placeholder="store.settings?.ai.hasKey?'已安全保存；留空保留现有密钥':'本地服务可留空'" autocomplete="new-password"/></label><p class="field-note"><KeyRound :size="13"/>密钥通过操作系统安全存储保护，不写入资料库 JSON。</p><div class="setting-actions"><button class="primary" :disabled="!loaded||!!store.busy||!form.baseURL||!form.model"><Save :size="15"/>保存模型设置</button><button v-if="store.settings?.ai.hasKey" type="button" @click="clearKey">移除密钥</button></div><p class="field-note">发送消息后，对话与工具查询到的课程、计划、资料元数据会发送到此服务。聊天记录保存在本机。</p></form></section><section class="settings-section"><h2><Server :size="19"/>MCP 连接</h2><form class="settings-card form-stack" @submit.prevent="saveMCP"><div class="setting-row"><div><strong>允许本机 MCP 客户端访问资料库</strong><p>绑定 127.0.0.1，使用 Bearer 令牌鉴权。</p></div><label class="switch"><input v-model="form.mcpEnabled" type="checkbox" aria-label="启用 MCP Server"/><span/></label></div><label>服务端口<input type="number" min="1024" max="65535" v-model="form.mcpPort" required/></label><div class="setting-actions"><button class="primary" :disabled="!loaded||!!store.busy">保存 MCP 设置</button><span class="service-state" :class="{enabled:store.settings?.mcp.enabled}"><span class="inline-dot"/>{{store.settings?.mcp.enabled?'服务已启用':'服务未启用'}}</span></div><template v-if="store.settings?.mcp.enabled&&store.settings.mcp.token"><div class="token-row"><code>{{showToken?store.settings.mcp.token:'••••••••••••••••••••••••'}}</code><button type="button" @click="showToken=!showToken">{{showToken?'隐藏':'显示令牌'}}</button><button type="button" @click="copyMCP"><Copy :size="14"/>复制配置</button></div><p class="field-note">持有令牌的本机客户端可调用已启用工具，请只配置到信任的客户端。</p></template></form></section><section class="settings-section"><h2><Monitor :size="19"/>外观</h2><div class="settings-card setting-row"><div><strong>显示模式</strong><p>选择适合当前环境的明暗主题。</p></div><select v-model="form.theme" aria-label="显示模式" @change="saveTheme"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div></section><section class="settings-section"><h2><Globe :size="19"/>教学网站</h2><div class="settings-card setting-row"><div><strong>南京大学教学平台与课表</strong><p>在隔离的 Chromium 窗口登录并读取当前页面。</p></div><button @click="emit('website')">打开教学网站工具</button></div></section></div></div></section></template>
